def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, 20.0))

    likely_units = int(max(1, supply // WATER_REQ))
    scarcity = likely_units <= 1

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive:
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        if opp.get('budget', 0) >= 140:
            rich_opp += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid', 0.0)))
            except Exception:
                pass

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 2

    if scarcity:
        danger += 1
    if urgent_opp >= 2:
        danger += 1

    if danger >= 6:
        base = max(95.0, highest_prev + 8.0)
    elif danger >= 4:
        base = max(72.0, highest_prev + 3.0, avg_prev + 6.0)
    elif danger >= 2:
        base = max(42.0, avg_prev * 0.7)
    else:
        base = 18.0 if scarcity else 12.0

    if highest_prev >= 150.0 and danger <= 2:
        base = min(base, 28.0)
    elif highest_prev >= 100.0 and danger <= 1:
        base = min(base, 22.0)

    if rich_opp >= 2 and danger >= 4:
        base += 8.0

    if budget < 60:
        base = min(base, budget)
    elif budget < 120:
        base = min(base, 0.75 * budget)
    else:
        base = min(base, 0.55 * budget)

    if day >= 8 and (hp <= 5 or no_water >= 1):
        base = max(base, min(budget, highest_prev + 5.0, 110.0))

    if day == 1 and hp >= 8:
        base = min(base, 26.0 if scarcity else 18.0)

    bid = max(0.0, min(float(budget), float(base)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            alive.append(o)

    if not alive:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # React to yesterday's bids (only immediate trace)
    prev_bids = []
    for o in alive:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    # Cindy appears the most aggressive from trace; hedge vs her by not matching her unless needed.
    # Use our hp/no_water_days to decide urgency.
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Urgency score: higher when hp is low or we've gone many days without water.
    urgency = 0
    if hp <= 2.0:
        urgency += 3
    elif hp <= 4.0:
        urgency += 2
    elif hp <= 7.0:
        urgency += 1

    if no_water_days >= 3:
        urgency += 3
    elif no_water_days == 2:
        urgency += 2
    elif no_water_days == 1:
        urgency += 1

    # Supply pressure: when supply is high, we can bid less and still expect allocation.
    # Map supply to a multiplier in [0.75, 1.15]
    if MAX_SUPPLY <= MIN_SUPPLY:
        supply_mult = 1.0
    else:
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        supply_mult = 0.75 + 0.4 * max(0.0, min(1.0, t))

    # Base bid target: moderate fraction of salary.
    # If Cindy-like aggression is present (high previous bid), we shade below it unless urgency is high.
    # highest_prev_bid threshold around 0.85*DAILY_SALARY = 76.5
    shaded = 0.55 * DAILY_SALARY
    if highest_prev_bid >= 0.85 * DAILY_SALARY:
        # Shade under the aggressor to avoid budget death; only escalate when urgency is high.
        if urgency >= 4:
            target = 0.95 * min(DAILY_SALARY, highest_prev_bid)
        elif urgency >= 2:
            target = 0.7 * min(DAILY_SALARY, highest_prev_bid)
        else:
            target = shaded * supply_mult
    else:
        # If no one is extremely aggressive yesterday, bid enough to stay competitive.
        if urgency >= 4:
            target = 0.9 * DAILY_SALARY
        elif urgency >= 2:
            target = 0.65 * DAILY_SALARY
        else:
            target = 0.5 * DAILY_SALARY
        target *= supply_mult

    # Ensure we don't overbid beyond our budget.
    # Also, if budget is low, bid nearly all remaining budget to prevent HP collapse.
    if budget <= 0:
        return 0.0

    # Budget-aware cap/floor
    low_budget = budget < 0.35 * DAILY_SALARY
    if low_budget:
        # Spend aggressively when we are already constrained.
        target = max(target, 0.85 * budget)

    bid = float(min(budget, max(0.0, target)))

    # Final safety: if we're in critical HP, bid to secure water.
    if hp <= 1.5:
        bid = float(min(budget, max(bid, 0.95 * DAILY_SALARY)))

    return bid

def get_bid(day_context, my_status, opponents_status):
